// Without context — props pass through every level
function App() {
  const [user, setUser] = useState({ name: 'Alice' });
  return <Layout user={user} />;
}

function Layout({ user }) {
  return <Header user={user} />; // Doesn't use user
}

function Header({ user }) {
  return <UserMenu user={user} />; // Doesn't use user
}

function UserMenu({ user }) {
  return <p>{user.name}</p>; // Finally uses user
}

import { createContext, useContext, useState } from 'react';

// 1. Create context with a default value
const UserContext = createContext(null);

// 2. Provide context at a high level
function App() {
  const [user, setUser] = useState({ name: 'Alice' });

  return (
    <UserContext.Provider value={{ user, setUser }}>
      <Layout />
    </UserContext.Provider>
  );
}

// 3. Consume anywhere in the tree
function UserMenu() {
  const { user } = useContext(UserContext);
  return <p>{user.name}</p>;
}

const ThemeContext = createContext('light');

// Outside any provider, this returns 'light'
function SomeRandomComponent() {
  const theme = useContext(ThemeContext); // 'light'
  return <p>{theme}</p>;
}
